server <- function(input, output, session) {

  # --- Selectores encadenados -------------------------------------------------

  observeEvent(input$segmento, {
    grupos <- publicos %>% filter(segmento == input$segmento) %>% pull(nivel)
    updateSelectInput(session, "nivel", choices = grupos, selected = grupos[1])
  })

  observeEvent(input$anio, {

    industrias <- rankings %>%
      filter(anio == as.integer(input$anio), !is.na(industria)) %>%
      distinct(industria) %>%
      arrange(industria) %>%
      pull(industria)

    walk(c("industria_ranking", "industria_tiempo"), \(control) {
      updateSelectInput(session, control,
                        choices = c("Todas", industrias), selected = "Todas")
    })

    bloque <- datos_por_edicion[[input$anio]]$territorios_consenso
    if (!is.null(bloque)) {
      resumen <- bloque$territorios %>% arrange(territorio)
      updateSelectInput(session, "territorio_elegido",
                        choices = set_names(resumen$territorio, resumen$nombre),
                        selected = resumen$territorio[1])
    }
  })

  observeEvent(list(input$anio, input$segmento), {
    grupos <- publicos %>% filter(segmento == input$segmento) %>% pull(nivel)
    updateSelectInput(session, "grupo_a", choices = grupos, selected = grupos[1])
    updateSelectInput(session, "grupo_b", choices = grupos,
                      selected = grupos[min(2, length(grupos))])
  })

  # --- El publico y la edicion vigentes ---------------------------------------

  publico <- reactive({
    elegido <- input$nivel %||% "Total"
    activo <- !identical(input$segmento %||% "Total", "Total")
    list(activo = activo,
         etiqueta = if (activo) elegido else "Total",
         # Para usar dentro de una frase: "entre las mujeres", "en el total".
         en_frase = if (activo) paste0("en el grupo ", elegido) else "en la muestra total")
  })

  observe({
    session$sendCustomMessage("publico", list(activo = publico()$activo,
                                              etiqueta = publico()$etiqueta))
  })

  observe({
    aplica <- is.null(input$pestana) || input$pestana %in% pestanas_por_publico
    session$sendCustomMessage("segmento_aplica", list(aplica = aplica))
  })

  personas_del_publico <- reactive({
    req(input$nivel)
    fila <- importancias %>%
      filter(anio == as.integer(input$anio),
             segmento == input$segmento, nivel == input$nivel)
    if (nrow(fila) == 0) NA_integer_ else max(fila$base)
  })

  output$base_segmento <- renderUI({
    n <- personas_del_publico()
    if (!publico()$activo || is.na(n)) return(NULL)
    div(class = "base-segmento", paste0(miles(n), " personas en el grupo"))
  })

  ranking_publico <- reactive({
    req(input$nivel)
    filas <- rankings %>%
      filter(anio == as.integer(input$anio),
             segmento == input$segmento, nivel == input$nivel,
             conocimiento >= base_minima_publico, !is.na(indice_empatia))
    validate(need(nrow(filas) > 0, "Sin marcas con base suficiente en este público."))
    filas %>% arrange(desc(indice_empatia))
  })

  output$contexto_ranking <- renderUI({
    filas <- ranking_publico()
    div(
      class = "contexto",
      h2("Mercado"),
      p(paste("Edición", input$anio, "·", nrow(filas), "marcas en el ranking EmpatIA"),
        if (publico()$activo) tags$span(class = "etiqueta-publico", publico()$etiqueta))
    )
  })

  # --- Cifras destacadas ------------------------------------------------------

  output$vb_marcas <- renderText(nrow(ranking_publico()))

  output$vb_marcas_pie <- renderText({
    paste(n_distinct(ranking_publico()$industria), "industrias")
  })

  output$vb_lider <- renderText(first(ranking_publico()$marca))

  output$vb_lider_pie <- renderText({
    lider <- ranking_publico() %>% slice(1)
    paste(na.omit(c(lider$industria, lider$categoria)), collapse = " · ")
  })

  output$vb_indice_lider <- renderText(formato(100 * first(ranking_publico()$indice_empatia)))

  output$vb_indice_lider_pie <- renderText({
    filas <- ranking_publico()
    if (nrow(filas) < 2) return("Única marca con base suficiente")
    paste(con_signo(100 * (filas$indice_empatia[1] - filas$indice_empatia[2])),
          "puntos sobre", filas$marca[2])
  })

  output$vb_personas <- renderText({
    n <- personas_del_publico()
    if (is.na(n)) "Sin datos" else miles(n)
  })

  output$vb_personas_pie <- renderText(paste("Edición", input$anio))

  # --- Ranking ----------------------------------------------------------------

  definicion_ranking <- reactive({
    configuracion <- datos_por_edicion[[input$anio]]$config
    paste0(
      "El ranking EmpatIA ordena las marcas del estudio según su Índice EmpatIA. ",
      "El índice combina dos atributos: la proporción de quienes evaluaron la marca ",
      "que la considera cercana (peso ", round(100 * (configuracion$peso_cercania %||% 0.5)),
      "%) y la que la considera tecnológica (", round(100 * (configuracion$peso_tecnologia %||% 0.5)),
      "%). Va de 0 a 100. Entran al ranking las marcas que conocen al menos ",
      base_minima_publico, " personas del público elegido; con menos, el puntaje es ",
      "demasiado inestable para ordenarlas."
    )
  })

  output$definicion_ranking <- renderUI(definicion_ranking())
  output$definicion_ranking_metodo <- renderUI(p(definicion_ranking()))

  output$ranking_grafico <- renderPlotly({

    filas <- ranking_publico()

    if (input$industria_ranking != "Todas") {
      filas <- filas %>% filter(industria == input$industria_ranking)
    }

    validate(need(nrow(filas) > 0, "Sin marcas de esa industria en este público."))

    etiqueta_eje <- c(indice_empatia = "Índice EmpatIA",
                      cercana = "Es cercana",
                      tecnologica = "Es tecnológica")[[input$orden_ranking]]

    datos_figura <- filas %>%
      mutate(valor = 100 * .data[[input$orden_ranking]]) %>%
      slice_max(valor, n = input$cuantas, with_ties = FALSE) %>%
      mutate(
        text = paste0(marca, "\n", coalesce(categoria, industria),
                      "\n", etiqueta_eje, ": ", formato(valor),
                      "\nConocen la marca: ", conocimiento)
      )

    figura <- datos_figura %>%
      ggplot(aes(x = reorder(marca, valor), y = valor,
                 fill = industria, text = text)) +
      geom_col(width = 0.74) +
      coord_flip() +
      scale_fill_manual(values = colores_industria, na.value = color_resto) +
      scale_y_continuous(expand = expansion(mult = c(0, 0.08))) +
      labs(x = NULL, y = paste0(etiqueta_eje, " · de cada 100"), fill = NULL)

    interactivo(figura)
  })

  output$pie_ranking <- renderUI({

    filas <- ranking_publico()
    podio <- filas %>% slice_head(n = 3)

    industria_arriba <- filas %>%
      slice_head(n = 10) %>%
      count(industria, sort = TRUE) %>%
      slice(1)

    conclusion(
      paste0("Lidera ", podio$marca[1], " con ", formato(100 * podio$indice_empatia[1]),
             " puntos",
             if (nrow(podio) == 3) {
               paste0(", seguida de ", podio$marca[2], " (", formato(100 * podio$indice_empatia[2]),
                      ") y ", podio$marca[3], " (", formato(100 * podio$indice_empatia[3]), ")")
             } else "",
             ". ", industria_arriba$industria, " aporta ", industria_arriba$n,
             " de las diez primeras marcas ", publico()$en_frase, ".")
    )
  })

  output$ranking_publicos <- renderPlotly({

    # Todos los grupos del estudio a la vez, no solo el elegido: la gracia de esta
    # figura es comparar entre grupos.
    filas <- puestos_por_grupo()

    orden_marcas <- rankings %>%
      filter(anio == as.integer(input$anio), segmento == "Total",
             marca %in% filas$marca) %>%
      arrange(indice_empatia) %>%
      pull(marca)

    datos_figura <- filas %>%
      mutate(
        marca = factor(marca, levels = orden_marcas),
        grupo = paste0(nivel, "\n(", nombre_segmento(segmento), ")"),
        text = paste0(marca, "\n", nivel, ": puesto ", puesto,
                      "\nÍndice EmpatIA: ", formato(100 * indice_empatia))
      )

    figura <- datos_figura %>%
      ggplot(aes(x = grupo, y = marca, fill = puesto, text = text)) +
      geom_tile(colour = "white", linewidth = 0.6) +
      # Escala de un solo tono: el puesto es una magnitud ordenada, no categorias.
      # Se invierte para que el primer lugar quede oscuro.
      scale_fill_gradient(low = "#4B1FE0", high = "#EFEAFF") +
      labs(x = NULL, y = NULL, fill = "Puesto") +
      theme_empatia_celdas()

    interactivo(figura)
  })

  puestos_por_grupo <- reactive({

    filas <- rankings %>%
      filter(anio == as.integer(input$anio), segmento != "Total",
             conocimiento >= base_minima_publico, !is.na(indice_empatia))

    validate(need(nrow(filas) > 0, "Sin resultados por público en esta edición."))

    # Las mejores del total, para que la figura quepa y para que las filas sean
    # las mismas en todas las columnas.
    mejores <- rankings %>%
      filter(anio == as.integer(input$anio), segmento == "Total",
             conocimiento >= base_minima_publico) %>%
      slice_max(indice_empatia, n = 22, with_ties = FALSE) %>%
      pull(marca)

    filas %>%
      filter(marca %in% mejores) %>%
      mutate(puesto = min_rank(desc(indice_empatia)), .by = c(segmento, nivel))
  })

  output$pie_publicos <- renderUI({

    filas <- puestos_por_grupo()

    vaivenes <- filas %>%
      summarise(mejor = min(puesto), peor = max(puesto),
                grupo_mejor = nivel[which.min(puesto)],
                grupo_peor = nivel[which.max(puesto)],
                grupos = n(), .by = marca) %>%
      filter(grupos >= 2) %>%
      arrange(desc(peor - mejor))

    if (nrow(vaivenes) == 0) return(NULL)

    mas_variable <- vaivenes %>% slice(1)

    primeros <- filas %>% filter(puesto == 1) %>% count(marca, sort = TRUE) %>% slice(1)
    total_grupos <- n_distinct(paste(filas$segmento, filas$nivel))

    conclusion(
      paste0("La marca cuyo puesto más depende del público es ", mas_variable$marca,
             ": #", mas_variable$mejor, " en ", mas_variable$grupo_mejor, " y #",
             mas_variable$peor, " en ", mas_variable$grupo_peor, ". ",
             primeros$marca, " es la primera en ", primeros$n, " de los ",
             total_grupos, " grupos.")
    )
  })

  trayectorias <- reactive({

    filas <- rankings %>%
      filter(segmento == input$segmento, nivel == input$nivel,
             conocimiento >= base_minima_publico, !is.na(indice_empatia))

    if (input$industria_tiempo != "Todas") {
      filas <- filas %>% filter(industria == input$industria_tiempo)
    }

    # Solo marcas medidas en dos o mas ediciones: con una sola no hay trayectoria.
    filas <- filas %>% filter(n_distinct(anio) >= 2, .by = marca)

    validate(need(nrow(filas) > 0,
                  "Ninguna marca de esa selección tiene dos ediciones comparables."))
    filas
  })

  output$ranking_tiempo <- renderPlotly({

    filas <- trayectorias()

    # Se dibujan las que llegaron mas alto en la ultima edicion disponible; el
    # resto quedaria ilegible.
